// eslint-disable
'use strict';

const logger = require('@yandex-int/yandex-logger')({
    streams: [
        {
            level: 'warn',
            stream: require('@yandex-int/yandex-logger/streams/error-booster')({
                // Название проекта, в scope которого складывать ошибки. Проект будет доступен на витрине https://error.yandex-team.ru/projects
                project: 'yours-project',
                // Путь до сокета unified_agent'а
                socketPath: '/tmp/unified.sock',
            })
        }
    ],
    fields: {
        env: process.env.NODE_ENV,
        version: process.env.APP_VERSION,
    },
});

// 1. Простое сообщение
logger.warn('Log message');

// 2. Логируем только ошибку
let err = new TypeError('Something went wrong!');
logger.error(err);

// 3. Логируем сложный объект
logger.error({
    method: '_getData',
    experiments: 'aaa=1;bb=7;ccc=yes;ddd',
    additional: {
        login: 'anonymous',
        key: 'value'
    }
});

// 5. Логируем с форматированием строки
logger.warn('Found %d errors', 2);
logger.warn('Found %d errors', 3);
logger.warn('Found %d errors', 5);
